import sys
from pathlib import Path


PROJECT_ROOT = Path(__file__).resolve().parent.parent
if str(PROJECT_ROOT) not in sys.path:
    sys.path.insert(0, str(PROJECT_ROOT))

from qitker.anyons.FusionSystem import FusionSystem
from qitker.parser.sequenceOperation import sequenceOperation


def apply_local(circuit, sequences, gate, qubit):
    """Apply a stored four-anyon gate to one logical qubit."""
    word = sequences.getSeq(gate)
    offset = 4 * qubit
    for sigma in word:
        sign = 1 if sigma > 0 else -1
        circuit.sigma_global(sign * (abs(sigma) + offset))
    return len(word)


def apply_global(circuit, sequences, gate):
    """Apply a stored eight-anyon controlled gate."""
    word = sequences.getSeq(gate)
    for sigma in word:
        circuit.sigma_global(sigma)
    return len(word)


def apply_both(circuit, sequences, gate):
    """Apply the same local gate to q[0] and q[1]."""
    return sum(
        apply_local(circuit, sequences, gate, qubit)
        for qubit in (0, 1)
    )


def grover_for_11(circuit, sequences):
    """Run one two-qubit Grover iteration whose marked state is |11>."""
    braid_count = 0

    # Prepare the uniform superposition.
    braid_count += apply_both(circuit, sequences, "H")

    # Oracle: CZ changes only the phase of |11>.
    braid_count += apply_global(circuit, sequences, "CZ")

    # Diffuser: H^2 X^2 CZ X^2 H^2, up to an irrelevant global phase.
    braid_count += apply_both(circuit, sequences, "H")
    braid_count += apply_both(circuit, sequences, "X")
    braid_count += apply_global(circuit, sequences, "CZ")
    braid_count += apply_both(circuit, sequences, "X")
    braid_count += apply_both(circuit, sequences, "H")

    return braid_count


