def main():
    circuit = FusionSystem(2)
    sequences = sequenceOperation()
    braid_count = grover_for_11(circuit, sequences)

    state = circuit.hilbertSpace.state_vector
    indices = circuit.basis.logical_to_physical

    # The ideal output after one iteration is |11>; do not postselect leakage.
    fidelity = abs(state[indices["11"]]) ** 2
    print("Two-qubit Grover search: marked state |11>")
    print(f"Physical braid count: {braid_count}")
    print(f"State fidelity: {100 * fidelity:.6f}%")
    print(f"Check (at least 99%): {'PASS' if fidelity >= 0.99 else 'FAIL'}")
    print("Outcome probabilities (ideal: 11=100%):")
    for label in ("00", "01", "10", "11"):
        print(f"  {label}: {100 * abs(state[indices[label]]) ** 2:.6f}%")
    print(f"  leakage: {100 * circuit.hilbertSpace.leakage_probability():.6f}%")


if __name__ == "__main__":
    main()
